 "content": "def transform(grid):
    """Expand diagonal markers into the periodic diagonal color field."""
    h, w = len(grid), len(grid[0])
    candidates = []
    for name, key_fn in (("sum", lambda r, c: r + c),
                         ("difference", lambda r, c: c - r)):
        clues = {}
        consistent = True
        for r, row in enumerate(grid):
            for c, color in enumerate(row):
                if color:
                    key = key_fn(r, c)
                    if key in clues and clues[key] != color:
                        consistent = False
                        break
                    clues[key] = color
            if not consistent:
                break
        if not consistent or not clues:
            continue
        for period in range(1, h + w + 1):
            residues = {}
            for key, color in clues.items():
                residue = key % period
                if residue in residues and residues[residue] != color:
                    break
                residues[residue] = color
            else:
                if len(residues) == period:
                    candidates.append((period, name, key_fn, residues))
                    break
    if not candidates:
        raise ValueError("diagonal clues do not determine a complete periodic field")
    period, _, key_fn, residues = min(candidates, key=lambda item: item[0])
    return [[residues[key_fn(r, c) % period] for c in range(w)]
            for r in range(h)]


